/*
 * Program ID   : PR_SCP_XLS_ADD_XLSPSI02_S
 * Description  : SCP SIMULATION SAVE
 * OutTable     :
 * Execute      :
                 EXEC PR_SCP_XLS_ADD_XLSPSI02_S


 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2023.09.25   DHJ            Initial Release PJ20230692  SCM 역량 강화 위한 SCP 개선과제 이행 Phase.2
 * 2023.12.12   OIJ            전달 변수를 지역변수로 변경하여 사용하도록 수정
 * 2024.09.06   KSK           프로시저의 주요파라미터정보를 로그에 기록함
 * 2026-08-07   ZIONEX         [PJ202650304] NextSCM Migration
 *     PR_SCP_XLS_ADD_XLSPSI02 가 반환값으로 2회차(2 year) 실행 여부를 가른다. 그래서 시그니처
 *       원본 L184 return -1 : PLAN_TYPE 이 FN 이면 수정금지 = ★정상 스킵(에러 아님)
 *       원본 L202 return -1 : 입력 버전과 현재 버전 불일치 = ★정상 스킵(에러 아님)
 *       원본 L1118 return 1 : OLD_CELL_SHIP_PLAN 은 PSI 저장까지만 하고 정상 종료
 *       원본 L3277 return -1 : CATCH 블록 = 에러(로그만 남기고 흡수, 원본대로 RAISE 하지 않는다)
 *       원본 L3302 return 1 : 정상 종료
 *   - 임시테이블 #temp 11종 -> GTT(GT_XPGT_*). DROP/CREATE 대신 각 사용 직전 DELETE 로 초기화.
 *     ★#DAY_SCP_XLS_PSI_GLOBAL 은 원본이 SCP_XLS_PSI_GLOBAL_SMALL_PACK(471컬럼) 의 SELECT INTO 인데
 *       SMALL_PACK 은 ESS 의 상위집합(CHILD_ITEM_ID / END_CUSTOMER / LAST_QTY 3컬럼이 더 있음)이고
 *   - WITH (NOLOCK) 은 Oracle 다중버전 읽기일관성으로 대응이 없어 전 구문에서 제거.
 *   - UPDATE .. FROM .. JOIN 은 원천 유일성이 보장되는 곳만 MERGE, 다중매치 가능성이 있는 곳은
 *     상관 UPDATE + EXISTS + ROWNUM = 1 로 옮겨 ORA-30926(비결정 갱신)을 원천 차단한다(CV-024).
 *   - MSSQL composable DML (INSERT .. SELECT FROM (MERGE .. OUTPUT $action) Changes WHERE Action=INSERT)
 *     은 Oracle 에 대응 구문이 없다. MERGE 가 INSERT 할 행 집합 = ON 절 미매칭 원천행이므로 MERGE 직전에
 *     NOT EXISTS 로 같은 집합을 뽑아 PROD_PLAN_ENGINE 짝 행을 먼저 INSERT 한다(MEASURE 가 달라 매칭 무영향).
 */
AS
    /*  전달 변수를 담는 지역변수 (원본 2023.12.12 OIJ 변경분) */
    V_BATCH_USER_ID              VARCHAR2(100 CHAR) := '';
    V_BATCH_DIVISION_ID          VARCHAR2(30 CHAR);
    V_BATCH_PLAN_START_YYYYMMDD  VARCHAR2(8 CHAR);
    V_BATCH_PLAN_TYPE            VARCHAR2(50 CHAR);
    V_BATCH_SEQ                  NUMBER(19);
    V_BATCH_ITEM_ID              VARCHAR2(50 CHAR);
    V_BATCH_MEASURE              VARCHAR2(50 CHAR);
    V_BATCH_XLS_KEY1             NUMBER(10);
    V_BATCH_LOADRATIO            VARCHAR2(20 CHAR);
    V_BATCH_CREATE_FROM_YYYYMMDD VARCHAR2(8 CHAR);
    V_BATCH_CREATE_TO_YYYYMMDD   VARCHAR2(8 CHAR);
    /*  LOG 용 변수 설정 */
    V_BATCH_USER                 VARCHAR2(150 CHAR) := '';
    V_PROGRAM_NAME               VARCHAR2(150 CHAR) := 'PR_SCP_XLS_ADD_XLSPSI02_S';
    V_LOG_TYPE                   VARCHAR2(30 CHAR);        /* START/END/ERROR/... */
    N_LOG_COUNT                  INTEGER := 0;
    V_LOG_MESSAGE                VARCHAR2(1000 CHAR);
    V_DESCRIPTION                VARCHAR2(500 CHAR);
    V_TABLE_ID                   VARCHAR2(150 CHAR) := 'SCP_XLS_PSI_GLOBAL';   /* 테이블 */
    D_EVENT_DATE                 DATE;
    /*  임시 실행시간 확인용 */
    V_START_TIME                 DATE;
    V_EXEC_TIME                  VARCHAR2(10 CHAR);        /* '[00:00]'; */
    /*  입력된 버전과 현재 버전 비교용 */
    V_DIVISION_ID                VARCHAR2(30 CHAR);
    V_PLAN_START_YYYYMMDD        VARCHAR2(8 CHAR);
    V_PLAN_TYPE                  VARCHAR2(50 CHAR);
    V_SEQ                        NUMBER(10);
    V_P_TO_YYYYMMDD              VARCHAR2(8 CHAR);
    /*  가동율 계산시간을 줄이기 위해서 FROM_SITE 추가 (원본 @p_from_site 는 파라미터가 아니라 지역변수다) */
    V_P_FROM_SITE                VARCHAR2(40 CHAR) := '';
    V_ORG_XLS_KEY1               VARCHAR2(200 CHAR);
    /*  BOD RANGE. ★Oracle 은 빈문자 = NULL 이라 초기값이 NULL 이 된다. 원본(MSSQL)에서 이 두 변수가 */
    V_BOD_FROM                   VARCHAR2(12 CHAR) := '';
    V_BOD_TO                     VARCHAR2(12 CHAR) := '';
    /*  HISTORY SEQ (원본은 선언만 하고 본문 사용 0건) */
    N_HISTORY_SEQ                INTEGER;
    /*  SCP_ANL_SHIPMENT_PLAN_FG/SEMI PK Parameter, SCP_ANL_PRODUCTION_PLAN PK Parameter */
    V_X_ITEM_ID                  VARCHAR2(50 CHAR);
    V_X_OPERATION_GROUP          VARCHAR2(50 CHAR);        /* BIZ_TYPE */
    V_X_PROJECT_CODE             VARCHAR2(50 CHAR);
    V_X_TO_SITE                  VARCHAR2(50 CHAR);
    V_X_INCOTERMS                VARCHAR2(50 CHAR);
    V_X_FROM_SITE                VARCHAR2(50 CHAR);        /* SCM_SITE_ID */
    V_X_BOD_ID                   VARCHAR2(50 CHAR);
    V_X_LINE_ID                  VARCHAR2(50 CHAR);
    V_X_OPERATION_ID             VARCHAR2(50 CHAR);
    /*  동적 SQL 조립 버퍼. MSSQL NVARCHAR(MAX) 이고 실측 조립길이가 364컬럼 x 약 90자 = 33,000자를 넘어 */
    V_MQRY_SUM2                  CLOB;
    V_MEXEC2                     CLOB;
    V_MFG                        CLOB;
    V_MSEMI                      CLOB;
    V_MPROD                      CLOB;
    V_MQRY_SUM                   CLOB;
    V_MEXEC                      CLOB;

    V_P_QTY001 PLS_INTEGER; V_P_QTY002 PLS_INTEGER; V_P_QTY003 PLS_INTEGER; V_P_QTY004 PLS_INTEGER; V_P_QTY005 PLS_INTEGER;
    V_P_QTY006 PLS_INTEGER; V_P_QTY007 PLS_INTEGER; V_P_QTY008 PLS_INTEGER; V_P_QTY009 PLS_INTEGER; V_P_QTY010 PLS_INTEGER;
