    V_P_QTY361 := P_QTY361; V_P_QTY362 := P_QTY362; V_P_QTY363 := P_QTY363; V_P_QTY364 := P_QTY364;

    /* LOG 용 변수 설정 */
    V_BATCH_USER      := V_BATCH_USER_ID;

  /*  시작 LOG */
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure ##########';
    V_DESCRIPTION     := V_PROGRAM_NAME || ':' || ' SCP_XLS_PSI_GLOBAL_SMALL_PACK SAVE LOGIC';
    D_EVENT_DATE      := SYSDATE;
    PR_SCP_SYS_LOG_BATCH( P_PROGRAM_NAME  => V_PROGRAM_NAME
                        , P_LOG_TYPE      => V_LOG_TYPE
                        , P_LOG_COUNT     => N_LOG_COUNT
                        , P_LOG_MESSAGE   => V_LOG_MESSAGE
                        , P_DESCRIPTION   => V_DESCRIPTION
                        , P_EVENT_DATE    => D_EVENT_DATE
                        , P_USER_ID       => V_BATCH_USER
                        );

        /*  임시 실행시간 확인용 */
    V_START_TIME      := SYSDATE;
    V_EXEC_TIME       := '';

    /* PRINT @p_plan_type */
    /*  PLAN_TYPE이 FN일경우 수정금지 RETURN */
    IF V_BATCH_PLAN_TYPE = 'FN' THEN
        /*  원본 L183~184 : if @v_batch_plan_type = 'FN' return -1 */
        O_RETURN_CODE := -1;
        RETURN;
    END IF;

    /* ------------------------------------------------------------------------------------------------------------- */
    /*  입력된 버전과 현재 버전이 다를 경우 RETURN */
    /* ------------------------------------------------------------------------------------------------------------- */
    V_DIVISION_ID           := V_BATCH_DIVISION_ID;
    V_PLAN_START_YYYYMMDD   := V_BATCH_PLAN_START_YYYYMMDD;
    V_PLAN_TYPE             := V_BATCH_PLAN_TYPE;
    V_SEQ                   := V_BATCH_SEQ;

    /*  MSSQL : SELECT TOP 1 @v_.. = .. FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK WHERE PLAN_START_YYYYMMDD = (MAX)
        0행이면 MSSQL 은 변수 기존값을 그대로 두므로 SELECT INTO(NO_DATA_FOUND/ORA-01422) 가 아니라 */
    FOR R IN ( SELECT DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                 FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK
                WHERE PLAN_START_YYYYMMDD = (SELECT MAX(PLAN_START_YYYYMMDD) FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK)   /* 2022.09.21 KSW 소형SCM개선요청사항 적용 */
                  AND ROWNUM = 1
             )
    LOOP
        V_DIVISION_ID           := R.DIVISION_ID;
        V_PLAN_START_YYYYMMDD   := R.PLAN_START_YYYYMMDD;
        V_PLAN_TYPE             := R.PLAN_TYPE;
        V_SEQ                   := R.SEQ;
    END LOOP;

    IF ( V_BATCH_DIVISION_ID <> V_DIVISION_ID OR V_BATCH_PLAN_START_YYYYMMDD <> V_PLAN_START_YYYYMMDD
         OR V_BATCH_PLAN_TYPE <> V_PLAN_TYPE OR V_BATCH_SEQ <> V_SEQ ) THEN
        /*  원본 L201~202 : 입력된 버전과 현재 버전 불일치 -> return -1 */
        O_RETURN_CODE := -1;
        RETURN;
    END IF;
    /* ------------------------------------------------------------------------------------------------------------- */

