            /*  SOURCE TABLE 반영 */
            /* ------------------------------------------------------------------------------------------- */
            /*  UI 작업자와 시물레이션 작업자를 구분하기 위해서 */
            /*                CASE 로 1:1 재현하고, NVARCHAR(150) 대입 시의 조용한 절단도 SUBSTR 로 재현한다. */
            V_BATCH_USER := CASE WHEN V_BATCH_USER_ID IS NULL
                                 THEN NULL
                                 ELSE SUBSTR(V_BATCH_USER_ID || '[SIMULATION]', 1, 150)
                            END;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FG UPDATE */
            /*  PACK_SHIP_PLAN  --> SCP_ANL_SHIPMENT_PLAN_FG.MEASURE 'SHIP_PLAN_AMEND' UPDATE */
            /* ------------------------------------------------------------------------------------------- */
            IF V_BATCH_MEASURE IN ('PACK_SHIP_PLAN', 'CELL_SHIP_PLAN') THEN   /* FG */

            /*  SHIP_PLAN */
               /*  IF OBJECT_ID('tempdb..#SCP_ANL_SHIPMENT_PLAN_FG') IS NOT NULL DROP TABLE #SCP_ANL_SHIPMENT_PLAN_FG */
               DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG;

               INSERT INTO GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG
                    ( DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                    , BIZ_TYPE
                    , PROJECT_CODE
                    , ITEM_ID
                    , TO_SITE
                    , INCOTERMS
                    , FROM_SITE
                    , BOD_ID
                    , TRANSPORT_MODE
                    , MEASURE
                    , YYYYMMDD
                    , QTY
                    , ORIGIN_FROM_DIVISION_ID
                    , ORIGIN_TO_DIVISION_ID
                    , ELECTRODE_TYPE
                    , ATTRIBUTE1
                    , YYYYMMDD_COLUMN )
            SELECT X.DIVISION_ID
                 , X.PLAN_START_YYYYMMDD
                 , X.PLAN_TYPE
                 , X.SEQ
                 , X.OPERATION_GROUP AS BIZ_TYPE
                 , X.PROJECT_CODE
                 /* , X.CELL_ITEM_ID */
                 , X.ITEM_ID
                 , X.TO_SITE
                 , X.INCOTERMS
                 , X.FROM_SITE
                 , X.BOD_ID
                 , X.TRANSPORT_MODE
                 , 'SHIP_PLAN_AMEND' AS MEASURE
                 , Y.YYYYMMDD AS YYYYMMDD
                 , X.QTY
                 , V_BATCH_DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
                 , V_BATCH_DIVISION_ID AS ORIGIN_TO_DIVISION_ID
                 , '' AS ELECTRODE_TYPE
                 , X.ATTRIBUTE1
                 , Y.YYYYMMDD_COLUMN
              FROM ( SELECT *
                       FROM GT_XPGT_DAY_SCP_XLS_PSI_GLOBAL
                      WHERE 0 = 0
                   )
                   UNPIVOT ( QTY FOR YYYYMMDD_COLUMN IN ( QTY001, QTY002, QTY003, QTY004, QTY005, QTY006, QTY007, QTY008, QTY009, QTY010
                                        , QTY011, QTY012, QTY013, QTY014, QTY015, QTY016, QTY017, QTY018, QTY019, QTY020
                                        , QTY021, QTY022, QTY023, QTY024, QTY025, QTY026, QTY027, QTY028, QTY029, QTY030
                                        , QTY031, QTY032, QTY033, QTY034, QTY035, QTY036, QTY037, QTY038, QTY039, QTY040
                                        , QTY041, QTY042, QTY043, QTY044, QTY045, QTY046, QTY047, QTY048, QTY049, QTY050
                                        , QTY051, QTY052, QTY053, QTY054, QTY055, QTY056, QTY057, QTY058, QTY059, QTY060
                                        , QTY061, QTY062, QTY063, QTY064, QTY065, QTY066, QTY067, QTY068, QTY069, QTY070
                                        , QTY071, QTY072, QTY073, QTY074, QTY075, QTY076, QTY077, QTY078, QTY079, QTY080
                                        , QTY081, QTY082, QTY083, QTY084, QTY085, QTY086, QTY087, QTY088, QTY089, QTY090
                                        , QTY091, QTY092, QTY093, QTY094, QTY095, QTY096, QTY097, QTY098, QTY099, QTY100
                                        , QTY101, QTY102, QTY103, QTY104, QTY105, QTY106, QTY107, QTY108, QTY109, QTY110
                                        , QTY111, QTY112, QTY113, QTY114, QTY115, QTY116, QTY117, QTY118, QTY119, QTY120
                                        , QTY121, QTY122, QTY123, QTY124, QTY125, QTY126, QTY127, QTY128, QTY129, QTY130
                                        , QTY131, QTY132, QTY133, QTY134, QTY135, QTY136, QTY137, QTY138, QTY139, QTY140
                                        , QTY141, QTY142, QTY143, QTY144, QTY145, QTY146, QTY147, QTY148, QTY149, QTY150
                                        , QTY151, QTY152, QTY153, QTY154, QTY155, QTY156, QTY157, QTY158, QTY159, QTY160
                                        , QTY161, QTY162, QTY163, QTY164, QTY165, QTY166, QTY167, QTY168, QTY169, QTY170
                                        , QTY171, QTY172, QTY173, QTY174, QTY175, QTY176, QTY177, QTY178, QTY179, QTY180
                                        , QTY181, QTY182, QTY183, QTY184, QTY185, QTY186, QTY187, QTY188, QTY189, QTY190
                                        , QTY191, QTY192, QTY193, QTY194, QTY195, QTY196, QTY197, QTY198, QTY199, QTY200
                                        , QTY201, QTY202, QTY203, QTY204, QTY205, QTY206, QTY207, QTY208, QTY209, QTY210
                                        , QTY211, QTY212, QTY213, QTY214, QTY215, QTY216, QTY217, QTY218, QTY219, QTY220
                                        , QTY221, QTY222, QTY223, QTY224, QTY225, QTY226, QTY227, QTY228, QTY229, QTY230
                                        , QTY231, QTY232, QTY233, QTY234, QTY235, QTY236, QTY237, QTY238, QTY239, QTY240
                                        , QTY241, QTY242, QTY243, QTY244, QTY245, QTY246, QTY247, QTY248, QTY249, QTY250
                                        , QTY251, QTY252, QTY253, QTY254, QTY255, QTY256, QTY257, QTY258, QTY259, QTY260
                                        , QTY261, QTY262, QTY263, QTY264, QTY265, QTY266, QTY267, QTY268, QTY269, QTY270
                                        , QTY271, QTY272, QTY273, QTY274, QTY275, QTY276, QTY277, QTY278, QTY279, QTY280
                                        , QTY281, QTY282, QTY283, QTY284, QTY285, QTY286, QTY287, QTY288, QTY289, QTY290
                                        , QTY291, QTY292, QTY293, QTY294, QTY295, QTY296, QTY297, QTY298, QTY299, QTY300
                                        , QTY301, QTY302, QTY303, QTY304, QTY305, QTY306, QTY307, QTY308, QTY309, QTY310
                                        , QTY311, QTY312, QTY313, QTY314, QTY315, QTY316, QTY317, QTY318, QTY319, QTY320
                                        , QTY321, QTY322, QTY323, QTY324, QTY325, QTY326, QTY327, QTY328, QTY329, QTY330
                                        , QTY331, QTY332, QTY333, QTY334, QTY335, QTY336, QTY337, QTY338, QTY339, QTY340
                                        , QTY341, QTY342, QTY343, QTY344, QTY345, QTY346, QTY347, QTY348, QTY349, QTY350
                                        , QTY351, QTY352, QTY353, QTY354, QTY355, QTY356, QTY357, QTY358, QTY359, QTY360
                                        , QTY361, QTY362, QTY363, QTY364
                                        )
                           ) X
                 , ( SELECT A.BASIS_YYYYMMDD AS YYYYMMDD
                                     /*  MSSQL REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(..))) + CONVERT(NVARCHAR, ROW_NUMBER() OVER(..)) */
                                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS YYYYMMDD_COLUMN
                                  FROM SCM_SYS_CALENDAR_M A
                                 WHERE A.BASIS_YYYYMMDD     >= V_BATCH_CREATE_FROM_YYYYMMDD
                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                               ) Y
                /*  PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - start */
             WHERE X.YYYYMMDD_COLUMN = Y.YYYYMMDD_COLUMN
               AND Y.YYYYMMDD >= V_BOD_FROM
               AND Y.YYYYMMDD <= V_BOD_TO
             /*  PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - end */
               AND X.DIVISION_ID          = V_BATCH_DIVISION_ID
               AND X.CREATE_FROM_YYYYMMDD = V_BATCH_CREATE_FROM_YYYYMMDD
               AND X.XLS_KEY1             = V_BATCH_XLS_KEY1
                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  2022.04.05   KSW            Daily/Monthly Bucket 변경건 적용 :: 변경된 Daily 건만 저장하는 로직추가 */
            /*  입력값이 -9 (변경건 아님) 건은 제외한다. */
            /* ------------------------------------------------------------------------------------------- */
            DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG
             WHERE QTY = -9
                 ;

        /* ------------------------------------------------------------------------------------------- */
        /*  FROZEN 구간 UPDATE */
        /*  PLANT SITE(SCM_MST_SITE)의 SHIP_FROZEN ,PROD_FROZEN를 주단위로 변경하여 FROZEN 구간을 저장 내역에서 삭제한다. */
        /* ------------------------------------------------------------------------------------------- */
               MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG X
                USING ( SELECT DIVISION_ID
                             , PLAN_START_YYYYMMDD
                             , PLAN_TYPE
                             , SEQ
                             , BIZ_TYPE
                             , PROJECT_CODE
                             /* , CELL_ITEM_ID */
                             , ITEM_ID
                             , TO_SITE
                             , INCOTERMS
                             , FROM_SITE
                             , BOD_ID
                             /* , TRANSPORT_MODE */
                             , MEASURE
                             , YYYYMMDD
                             , QTY
                             , ORIGIN_FROM_DIVISION_ID
                             , ORIGIN_TO_DIVISION_ID
                             , ELECTRODE_TYPE
                          FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG
                         /* WHERE QTY > 0 */
                      ) Y
                   ON ( 0 = 0
                        AND X.DIVISION_ID               = Y.DIVISION_ID          /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                        AND X.PLAN_START_YYYYMMDD       = Y.PLAN_START_YYYYMMDD  /* @v_batch_PLAN_START_YYYYMMDD */
                        AND X.PLAN_TYPE                 = Y.PLAN_TYPE            /* @v_batch_PLAN_TYPE */
                        AND X.SEQ                       = Y.SEQ                  /* @v_batch_SEQ */
                        AND X.BIZ_TYPE                  = Y.BIZ_TYPE
                        AND X.PROJECT_CODE              = Y.PROJECT_CODE
                        AND X.ITEM_ID                   = Y.ITEM_ID
                        AND X.TO_SITE                   = Y.TO_SITE
                        AND X.INCOTERMS                 = Y.INCOTERMS
                        AND X.FROM_SITE                 = Y.FROM_SITE
                        AND X.BOD_ID                    = Y.BOD_ID
                        AND X.MEASURE                   = Y.MEASURE
                        AND X.YYYYMMDD                  = Y.YYYYMMDD )
                WHEN MATCHED THEN
                UPDATE
                   SET X.QTY               = Y.QTY
                     /* , X.CREATED_BY         = @v_batch_user */
                     /* , X.CREATION_DATE      = GETDATE()     */
                     , X.LAST_UPDATED_BY  = V_BATCH_USER
                     , X.LAST_UPDATE_DATE = SYSDATE
                WHEN NOT MATCHED THEN
                  INSERT ( DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , SEQ
                         , BIZ_TYPE
                         , PROJECT_CODE
                         /* , CELL_ITEM_ID */
                         , ITEM_ID
                         , TO_SITE
                         , INCOTERMS
                         , FROM_SITE
                         , BOD_ID
                         /* , TRANSPORT_MODE */
                         , MEASURE
                         , YYYYMMDD
                         , QTY
                         , ORIGIN_FROM_DIVISION_ID
                         , ORIGIN_TO_DIVISION_ID
                         , ELECTRODE_TYPE
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE )
                  VALUES ( Y.DIVISION_ID
                         , Y.PLAN_START_YYYYMMDD
                         , Y.PLAN_TYPE
                         , Y.SEQ
                         , Y.BIZ_TYPE
                         , Y.PROJECT_CODE
                         /* , Y.CELL_ITEM_ID */
                         , Y.ITEM_ID
                         , Y.TO_SITE
                         , Y.INCOTERMS
                         , Y.FROM_SITE
                         , Y.BOD_ID
                         /* , Y.TRANSPORT_MODE */
                         , Y.MEASURE
                         , Y.YYYYMMDD
                         , Y.QTY
                         , Y.ORIGIN_FROM_DIVISION_ID
                         , Y.ORIGIN_TO_DIVISION_ID
                         , Y.ELECTRODE_TYPE
                         , V_BATCH_USER
                         , SYSDATE
                         , V_BATCH_USER
                         , SYSDATE )
                         ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FG_H : History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SELECT top 10 * FROM dbo.SCP_ANL_SHIPMENT_PLAN_FG_H WITH (NOLOCK)      HISTORY_SEQ */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H */
                      INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG_H
                           ( HISTORY_SEQ
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , BIZ_TYPE
                           , PROJECT_CODE
                           , ITEM_ID
                           , TO_SITE
                           , INCOTERMS
                           , FROM_SITE
                           , BOD_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_TO_DIVISION_ID
                           , ORIGIN_FROM_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H.NEXTVAL
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , BIZ_TYPE
                           , PROJECT_CODE
                           , ITEM_ID
                           , TO_SITE
                           , INCOTERMS
                           , FROM_SITE
                           , BOD_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_TO_DIVISION_ID
                           , ORIGIN_FROM_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG
                           ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FIX : FIX 입력(FG) */
            /* ------------------------------------------------------------------------------------------- */
                        /*  FIX UPDATE */
                        /*  MSSQL UPDATE X SET .. FROM SCP_ANL_SHIPMENT_PLAN_FIX X INNER JOIN #FG Y ON ..
                            -> 원천 다중매치가 가능하므로 상관 UPDATE + EXISTS + ROWNUM = 1 (CV-024) */
                        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
                           SET ( QTY
                               , ATTRIBUTE1
                               , LAST_UPDATED_BY
                               , LAST_UPDATE_DATE ) =
                               ( SELECT Y.QTY
                                      , 'Y'                    /* History 구분을 위해 */
                                      , V_BATCH_USER
                                      , SYSDATE
                                   FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG Y
                                  WHERE 0 = 0
                                    AND X.DIVISION_ID  = Y.DIVISION_ID
                                    AND X.BIZ_TYPE     = Y.BIZ_TYPE
                                    AND X.PROJECT_CODE = Y.PROJECT_CODE
                                    AND X.ITEM_ID      = Y.ITEM_ID
                                    AND X.TO_SITE      = Y.TO_SITE
                                    AND X.FROM_SITE    = Y.FROM_SITE
                                    AND X.BOD_ID       = Y.BOD_ID
                                    AND X.YYYYMMDD     = Y.YYYYMMDD
                                    AND ROWNUM         = 1 )
                         WHERE EXISTS ( SELECT 1
                                          FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG Y
                                         WHERE 0 = 0
                                           AND X.DIVISION_ID  = Y.DIVISION_ID
                                           AND X.BIZ_TYPE     = Y.BIZ_TYPE
                                           AND X.PROJECT_CODE = Y.PROJECT_CODE
                                           AND X.ITEM_ID      = Y.ITEM_ID
                                           AND X.TO_SITE      = Y.TO_SITE
                                           AND X.FROM_SITE    = Y.FROM_SITE
                                           AND X.BOD_ID       = Y.BOD_ID
                                           AND X.YYYYMMDD     = Y.YYYYMMDD );

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_FIX_H   -- 현재 사용안함. */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H -- SCP_ANL_PRODUCTION_PLAN_FIX 대신 사용중임. */
            /*  SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H */
                      INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
                           ( HISTORY_SEQ
                           , FIX_ID
                           , DIVISION_ID
                           , BIZ_TYPE
                           , ITEM_ID
                           , TO_SITE
                           , FROM_SITE
                           , PROJECT_CODE
                           , INCOTERMS
                           , BOD_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
                           , FIX_ID
                           , DIVISION_ID
                           , BIZ_TYPE
                           , ITEM_ID
                           , TO_SITE
                           , FROM_SITE
                           , PROJECT_CODE
                           , INCOTERMS
                           , BOD_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM SCP_ANL_SHIPMENT_PLAN_FIX
                       WHERE ATTRIBUTE1 = 'Y'
                           ;

                  /*  History 구분을 위해 원상복구 */
                  UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
                     SET X.ATTRIBUTE1 = NULL
                   WHERE EXISTS ( SELECT 1
                                    FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_FG Y
                                   WHERE 0 = 0
                                     AND X.DIVISION_ID  = Y.DIVISION_ID
                                     AND X.BIZ_TYPE     = Y.BIZ_TYPE
                                     AND X.PROJECT_CODE = Y.PROJECT_CODE
                                     AND X.ITEM_ID      = Y.ITEM_ID
                                     AND X.TO_SITE      = Y.TO_SITE
                                     AND X.FROM_SITE    = Y.FROM_SITE
                                     AND X.BOD_ID       = Y.BOD_ID
                                     AND X.YYYYMMDD     = Y.YYYYMMDD )
                     AND X.ATTRIBUTE1 = 'Y';

            END IF;
            DBMS_OUTPUT.PUT_LINE('5555555555555555555555555555');
            /* ------------------------------------------------------------------------------------------- */
            /*  2021.04.2 KSW C20210420-000399-소형 Pack 시뮬레이터 Cell - Packer 반제품 Shipment 저장 가능하도록 수정 - start */
            /*                - CELL_SHIP_PLAN (Ship Plan(SCP)) Measure 를 SEMI_SHIP_PLAN 에 준하여 처리하는 로직을 추가 */
            /*  PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 :: ISUZU 적용 - SEMI_SHIP_PLAN case 추가 */
            /*  SCP_ANL_SHIPMENT_PLAN_SEMI UPDATE */
            /*  SEMI_SHIP_PLAN --> SCP_ANL_SHIPMENT_PLAN_SEMI.MEASURE 'SHIP_PLAN_AMEND' UPDATE */
            /* ------------------------------------------------------------------------------------------- */
            IF V_BATCH_MEASURE IN ('CELL_SHIP_PLAN', 'SEMI_SHIP_PLAN') THEN   /* SEMI */

            /*  SEMI_SHIP_PLAN */
              /*  IF OBJECT_ID('tempdb..#SCP_ANL_SHIPMENT_PLAN_SEMI') IS NOT NULL DROP TABLE #SCP_ANL_SHIPMENT_PLAN_SEMI */
              DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI;

              INSERT INTO GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI
                   ( DIVISION_ID
                   , PLAN_START_YYYYMMDD
                   , PLAN_TYPE
                   , SEQ
                   , OPERATION_GROUP
                   , ITEM_ID
                   , FROM_SITE
                   , BOD_ID
                   , MEASURE
                   , YYYYMMDD
                   , TO_SITE
                   , QTY
                   , ORIGIN_FROM_DIVISION_ID
                   , ORIGIN_TO_DIVISION_ID
                   , ELECTRODE_TYPE
                   , ATTRIBUTE1
                   , YYYYMMDD_COLUMN )
            SELECT X.DIVISION_ID
                 , X.PLAN_START_YYYYMMDD
                 , X.PLAN_TYPE
                 , X.SEQ
                 , X.OPERATION_GROUP
                 /* , X.CELL_ITEM_ID */
                 , X.ITEM_ID
                 , X.FROM_SITE
                 , X.BOD_ID
                 , 'SHIP_PLAN_AMEND' AS MEASURE
                 , Y.YYYYMMDD AS YYYYMMDD
                 , X.TO_SITE
                 , X.QTY
                 , '40' AS ORIGIN_FROM_DIVISION_ID
                 , '40' AS ORIGIN_TO_DIVISION_ID
                 , '' AS ELECTRODE_TYPE
                 , X.ATTRIBUTE1
                 , Y.YYYYMMDD_COLUMN
              FROM ( SELECT *
                       FROM GT_XPGT_DAY_SCP_XLS_PSI_GLOBAL
                      WHERE 0 = 0
                   )
                   UNPIVOT ( QTY FOR YYYYMMDD_COLUMN IN ( QTY001, QTY002, QTY003, QTY004, QTY005, QTY006, QTY007, QTY008, QTY009, QTY010
                                        , QTY011, QTY012, QTY013, QTY014, QTY015, QTY016, QTY017, QTY018, QTY019, QTY020
                                        , QTY021, QTY022, QTY023, QTY024, QTY025, QTY026, QTY027, QTY028, QTY029, QTY030
                                        , QTY031, QTY032, QTY033, QTY034, QTY035, QTY036, QTY037, QTY038, QTY039, QTY040
                                        , QTY041, QTY042, QTY043, QTY044, QTY045, QTY046, QTY047, QTY048, QTY049, QTY050
                                        , QTY051, QTY052, QTY053, QTY054, QTY055, QTY056, QTY057, QTY058, QTY059, QTY060
                                        , QTY061, QTY062, QTY063, QTY064, QTY065, QTY066, QTY067, QTY068, QTY069, QTY070
                                        , QTY071, QTY072, QTY073, QTY074, QTY075, QTY076, QTY077, QTY078, QTY079, QTY080
                                        , QTY081, QTY082, QTY083, QTY084, QTY085, QTY086, QTY087, QTY088, QTY089, QTY090
                                        , QTY091, QTY092, QTY093, QTY094, QTY095, QTY096, QTY097, QTY098, QTY099, QTY100
                                        , QTY101, QTY102, QTY103, QTY104, QTY105, QTY106, QTY107, QTY108, QTY109, QTY110
                                        , QTY111, QTY112, QTY113, QTY114, QTY115, QTY116, QTY117, QTY118, QTY119, QTY120
                                        , QTY121, QTY122, QTY123, QTY124, QTY125, QTY126, QTY127, QTY128, QTY129, QTY130
                                        , QTY131, QTY132, QTY133, QTY134, QTY135, QTY136, QTY137, QTY138, QTY139, QTY140
                                        , QTY141, QTY142, QTY143, QTY144, QTY145, QTY146, QTY147, QTY148, QTY149, QTY150
                                        , QTY151, QTY152, QTY153, QTY154, QTY155, QTY156, QTY157, QTY158, QTY159, QTY160
                                        , QTY161, QTY162, QTY163, QTY164, QTY165, QTY166, QTY167, QTY168, QTY169, QTY170
                                        , QTY171, QTY172, QTY173, QTY174, QTY175, QTY176, QTY177, QTY178, QTY179, QTY180
                                        , QTY181, QTY182, QTY183, QTY184, QTY185, QTY186, QTY187, QTY188, QTY189, QTY190
                                        , QTY191, QTY192, QTY193, QTY194, QTY195, QTY196, QTY197, QTY198, QTY199, QTY200
                                        , QTY201, QTY202, QTY203, QTY204, QTY205, QTY206, QTY207, QTY208, QTY209, QTY210
                                        , QTY211, QTY212, QTY213, QTY214, QTY215, QTY216, QTY217, QTY218, QTY219, QTY220
                                        , QTY221, QTY222, QTY223, QTY224, QTY225, QTY226, QTY227, QTY228, QTY229, QTY230
                                        , QTY231, QTY232, QTY233, QTY234, QTY235, QTY236, QTY237, QTY238, QTY239, QTY240
                                        , QTY241, QTY242, QTY243, QTY244, QTY245, QTY246, QTY247, QTY248, QTY249, QTY250
                                        , QTY251, QTY252, QTY253, QTY254, QTY255, QTY256, QTY257, QTY258, QTY259, QTY260
                                        , QTY261, QTY262, QTY263, QTY264, QTY265, QTY266, QTY267, QTY268, QTY269, QTY270
                                        , QTY271, QTY272, QTY273, QTY274, QTY275, QTY276, QTY277, QTY278, QTY279, QTY280
                                        , QTY281, QTY282, QTY283, QTY284, QTY285, QTY286, QTY287, QTY288, QTY289, QTY290
                                        , QTY291, QTY292, QTY293, QTY294, QTY295, QTY296, QTY297, QTY298, QTY299, QTY300
                                        , QTY301, QTY302, QTY303, QTY304, QTY305, QTY306, QTY307, QTY308, QTY309, QTY310
                                        , QTY311, QTY312, QTY313, QTY314, QTY315, QTY316, QTY317, QTY318, QTY319, QTY320
                                        , QTY321, QTY322, QTY323, QTY324, QTY325, QTY326, QTY327, QTY328, QTY329, QTY330
                                        , QTY331, QTY332, QTY333, QTY334, QTY335, QTY336, QTY337, QTY338, QTY339, QTY340
                                        , QTY341, QTY342, QTY343, QTY344, QTY345, QTY346, QTY347, QTY348, QTY349, QTY350
                                        , QTY351, QTY352, QTY353, QTY354, QTY355, QTY356, QTY357, QTY358, QTY359, QTY360
                                        , QTY361, QTY362, QTY363, QTY364
                                        )
                           ) X
                 , ( SELECT A.BASIS_YYYYMMDD AS YYYYMMDD
                                     /*  MSSQL REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(..))) + CONVERT(NVARCHAR, ROW_NUMBER() OVER(..)) */
                                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS YYYYMMDD_COLUMN
                                  FROM SCM_SYS_CALENDAR_M A
                                 WHERE A.BASIS_YYYYMMDD     >= V_BATCH_CREATE_FROM_YYYYMMDD
                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                               ) Y
                /*  KSK,  v_batch_create_from_yyyymmdd => @v_batch_create_to_yyyymmdd 기간일자 오류수정 (2024-02-23) */
             /*  PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - start */
             WHERE X.YYYYMMDD_COLUMN = Y.YYYYMMDD_COLUMN
               AND Y.YYYYMMDD >= V_BOD_FROM
               AND Y.YYYYMMDD <= V_BOD_TO
             /*  PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - end */
               AND Y.YYYYMMDD             >= V_BATCH_CREATE_FROM_YYYYMMDD   /* @v_batch_PLAN_START_YYYYMMDD  DHJ */
               AND X.DIVISION_ID          = V_BATCH_DIVISION_ID
               AND X.CREATE_FROM_YYYYMMDD = V_BATCH_CREATE_FROM_YYYYMMDD
               AND X.XLS_KEY1             = V_BATCH_XLS_KEY1
                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  2022.04.05   KSW            Daily/Monthly Bucket 변경건 적용 :: 변경된 Daily 건만 저장하는 로직추가 */
            /*  입력값이 -9 (변경건 아님) 건은 제외한다. */
            /* ------------------------------------------------------------------------------------------- */
            DELETE FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI
             WHERE QTY = -9
                 ;

            /* SELECT '#SCP_ANL_SHIPMENT_PLAN_SEMI' TN, * FROM #SCP_ANL_SHIPMENT_PLAN_SEMI WHERE QTY > 0 */
            DBMS_OUTPUT.PUT_LINE('#SCP_ANL_SHIPMENT_PLAN_SEMI PREPARED');

            /* ------------------------------------------------------------------------------------------- */
            /*  FROZEN 구간 UPDATE */
            /*  PLANT SITE(SCM_MST_SITE)의 SHIP_FROZEN ,PROD_FROZEN를 주단위로 변경하여 FROZEN 구간을 저장 내역에서 삭제한다. */
            /* ------------------------------------------------------------------------------------------- */
            /*  2021.12.06 SEMI SHIP PLAN(CELL_SHIP_PLAN) 에 대한 PR/MA Frozen 구간해제
               IF @p_plan_type IN  ('MA','SE')
               BEGIN
                 DELETE  FROM #SCP_ANL_SHIPMENT_PLAN_SEMI
                         FROM #SCP_ANL_SHIPMENT_PLAN_SEMI X
                       INNER JOIN #SCM_MST_SITE Y
                          ON Y.DIVISION_ID = X.DIVISION_ID
                         AND Y.SCM_SITE_ID = X.FROM_SITE
                       WHERE
                           X.YYYYMMDD < Y.SHIP_FROZEN_WEEK_DAY;
               END */

               MERGE INTO SCP_ANL_SHIPMENT_PLAN_SEMI X
                USING ( SELECT DIVISION_ID
                             , PLAN_START_YYYYMMDD   /* PLAN_START_YYYYMMDD  DHJ */
                             , PLAN_TYPE
                             , SEQ
                             , OPERATION_GROUP
                             /* , CELL_ITEM_ID */
                             , ITEM_ID
                             , FROM_SITE
                             , BOD_ID
                             , MEASURE
                             , YYYYMMDD
                             , TO_SITE
                             , QTY
                             , ORIGIN_FROM_DIVISION_ID
                             , ORIGIN_TO_DIVISION_ID
                             , ELECTRODE_TYPE
                          FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI
                         /* WHERE QTY > 0 */
                      ) Y
                   ON ( 0 = 0
                        AND X.DIVISION_ID         = Y.DIVISION_ID           /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                        AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD   /* @v_batch_PLAN_START_YYYYMMDD */
                        /*	AND X.PLAN_START_YYYYMMDD = Y.CREATE_FROM_YYYYMMDD		 DHJ */
                        AND X.PLAN_TYPE           = Y.PLAN_TYPE             /* @v_batch_PLAN_TYPE */
                        AND X.SEQ                 = Y.SEQ                   /* @v_batch_SEQ */
                        AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                        AND X.ITEM_ID             = Y.ITEM_ID
                        AND X.FROM_SITE           = Y.FROM_SITE
                        AND X.BOD_ID              = Y.BOD_ID
                        AND X.MEASURE             = Y.MEASURE
                        AND X.YYYYMMDD            = Y.YYYYMMDD
                        AND X.TO_SITE             = Y.TO_SITE )
                WHEN MATCHED THEN
                UPDATE
                   SET X.QTY               = Y.QTY
                     /* , X.CREATED_BY         = @v_batch_user */
                     /* , X.CREATION_DATE      = GETDATE()     */
                     , X.LAST_UPDATED_BY  = V_BATCH_USER
                     , X.LAST_UPDATE_DATE = SYSDATE
                WHEN NOT MATCHED THEN
                  INSERT ( DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , SEQ
                         , OPERATION_GROUP
                         , ITEM_ID
                         , FROM_SITE
                         , BOD_ID
                         , MEASURE
                         , YYYYMMDD
                         , TO_SITE
                         , QTY
                         , ORIGIN_FROM_DIVISION_ID
                         , ORIGIN_TO_DIVISION_ID
                         , ELECTRODE_TYPE
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE )
                  VALUES ( Y.DIVISION_ID
                         , Y.PLAN_START_YYYYMMDD   /* PLAN_START_YYYYMMDD  DHJ */
                         , Y.PLAN_TYPE
                         , Y.SEQ
                         , Y.OPERATION_GROUP
                         , Y.ITEM_ID
                         , Y.FROM_SITE
                         , Y.BOD_ID
                         , Y.MEASURE
                         , Y.YYYYMMDD
                         , Y.TO_SITE
                         , Y.QTY
                         , Y.ORIGIN_FROM_DIVISION_ID
                         , Y.ORIGIN_TO_DIVISION_ID
                         , Y.ELECTRODE_TYPE
                         , V_BATCH_USER
                         , SYSDATE
                         , V_BATCH_USER
                         , SYSDATE )
                         ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_SEMI_H : History 입력(SEMI) */
            /* ------------------------------------------------------------------------------------------- */
                      INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI_H
                           ( HISTORY_SEQ
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , ITEM_ID
                           , FROM_SITE
                           , TO_SITE
                           , BOD_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , UPDATE_REASON_BOD
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_SEMI_H.NEXTVAL
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , ITEM_ID
                           , FROM_SITE
                           , TO_SITE
                           , BOD_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , NULL AS UPDATE_REASON_BOD
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI
                           ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FIX : FIX 입력(SEMI) */
            /* ------------------------------------------------------------------------------------------- */
                        /*  FIX UPDATE */
                        /*  MSSQL UPDATE X SET .. FROM SCP_ANL_SHIPMENT_PLAN_FIX X INNER JOIN #SEMI Y ON ..
                            -> 원천 다중매치가 가능하므로 상관 UPDATE + EXISTS + ROWNUM = 1 (CV-024) */
                        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
                           SET ( QTY
                               , FIX_REASON
                               , ATTRIBUTE1 ) =
                               ( SELECT Y.QTY
                                      , 'SIMULATION UPDATE'
                                      , 'Y'                    /* History 구분을 위해 */
                                   FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI Y
                                  WHERE 0 = 0
                                    AND X.DIVISION_ID = Y.DIVISION_ID
                                    AND X.BIZ_TYPE    = Y.OPERATION_GROUP
                                    AND X.ITEM_ID     = Y.ITEM_ID
                                    AND X.TO_SITE     = Y.TO_SITE
                                    AND X.FROM_SITE   = Y.FROM_SITE
                                    AND X.BOD_ID      = Y.BOD_ID
                                    AND X.YYYYMMDD    = Y.YYYYMMDD
                                    AND ROWNUM        = 1 )
                         WHERE EXISTS ( SELECT 1
                                          FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI Y
                                         WHERE 0 = 0
                                           AND X.DIVISION_ID = Y.DIVISION_ID
                                           AND X.BIZ_TYPE    = Y.OPERATION_GROUP
                                           AND X.ITEM_ID     = Y.ITEM_ID
                                           AND X.TO_SITE     = Y.TO_SITE
                                           AND X.FROM_SITE   = Y.FROM_SITE
                                           AND X.BOD_ID      = Y.BOD_ID
                                           AND X.YYYYMMDD    = Y.YYYYMMDD );

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_SHIPMENT_PLAN_FIX_H : FIX History 입력(SEMI) */
            /* ------------------------------------------------------------------------------------------- */
                      INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
                           ( HISTORY_SEQ
                           , FIX_ID
                           , DIVISION_ID
                           , BIZ_TYPE
                           , ITEM_ID
                           , TO_SITE
                           , FROM_SITE
                           , PROJECT_CODE
                           , INCOTERMS
                           , BOD_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
                           , FIX_ID
                           , DIVISION_ID
                           , BIZ_TYPE
                           , ITEM_ID
                           , TO_SITE
                           , FROM_SITE
                           , PROJECT_CODE
                           , INCOTERMS
                           , BOD_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_FROM_DIVISION_ID
                           , ORIGIN_TO_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM SCP_ANL_SHIPMENT_PLAN_FIX
                       WHERE ATTRIBUTE1 = 'Y'
                           ;

                  /*  FIX UPDATE */
                  UPDATE SCP_ANL_SHIPMENT_PLAN_FIX X   /* FIX_ID, DIVISION_ID, BIZ_TYPE, ITEM_ID, TO_SITE, FROM_SITE, BOD_ID, YYYYMMDD */
                     SET X.ATTRIBUTE1 = NULL       /* History 구분을 위해 원상복구 */
                   WHERE EXISTS ( SELECT 1
                                    FROM GT_XPGT_SCP_ANL_SHIPMENT_PLAN_SEMI Y
                                   WHERE 0 = 0
                                     AND X.DIVISION_ID = Y.DIVISION_ID
                                     AND X.BIZ_TYPE    = Y.OPERATION_GROUP
                                     AND X.ITEM_ID     = Y.ITEM_ID
                                     AND X.TO_SITE     = Y.TO_SITE
                                     AND X.FROM_SITE   = Y.FROM_SITE
                                     AND X.BOD_ID      = Y.BOD_ID
                                     AND X.YYYYMMDD    = Y.YYYYMMDD )
                     AND X.ATTRIBUTE1 = 'Y';

            END IF;

            /*  2021.04.2 KSW C20210420-000399-소형 Pack 시뮬레이터 Cell - Packer 반제품 Shipment 저장 가능하도록 수정 - end */
            /* ------------------------------------------------------------------------------------------- */
            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN UPDATE */
            /*  PACK_PROD  --> SCP_ANL_PRODUCTION_PLAN.MEASURE 'PROD_PLAN_AMEND' UPDATE */
            /* ------------------------------------------------------------------------------------------- */
            IF V_BATCH_MEASURE IN ('PACK_PROD') THEN

               /*  IF OBJECT_ID('tempdb..#SCP_ANL_PRODUCTION_PLAN') IS NOT NULL DROP TABLE #SCP_ANL_PRODUCTION_PLAN */
               DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN;

               INSERT INTO GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                    ( DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                    , OPERATION_GROUP
                    , SCM_SITE_ID
                    , ITEM_ID
                    , LINE_ID
                    , OPERATION_ID
                    , MEASURE
                    , YYYYMMDD
                    , QTY
                    , ORIGIN_DIVISION_ID
                    , ELECTRODE_TYPE
                    , CELL_QTY
                    , YYYYMMDD_COLUMN )
            SELECT X.DIVISION_ID
                 , X.PLAN_START_YYYYMMDD
                 , X.PLAN_TYPE
                 , X.SEQ
                 , X.OPERATION_GROUP
                 /* , X.CELL_ITEM_ID */
                 , X.FROM_SITE AS SCM_SITE_ID
                 , X.ITEM_ID
                 , X.PROD_LINE AS LINE_ID
                 , X.ATTRIBUTE9 AS OPERATION_ID
                 , 'PROD_PLAN_AMEND' AS MEASURE
                 , Y.YYYYMMDD AS YYYYMMDD
                 , X.QTY
                 , X.DIVISION_ID AS ORIGIN_DIVISION_ID
                 , '' AS ELECTRODE_TYPE
                 , X.CELL_QTY_PACK AS CELL_QTY
                 , Y.YYYYMMDD_COLUMN
              FROM ( SELECT *
                       FROM GT_XPGT_DAY_SCP_XLS_PSI_GLOBAL
                      WHERE 0 = 0
                   )
                   UNPIVOT ( QTY FOR YYYYMMDD_COLUMN IN ( QTY001, QTY002, QTY003, QTY004, QTY005, QTY006, QTY007, QTY008, QTY009, QTY010
                                        , QTY011, QTY012, QTY013, QTY014, QTY015, QTY016, QTY017, QTY018, QTY019, QTY020
                                        , QTY021, QTY022, QTY023, QTY024, QTY025, QTY026, QTY027, QTY028, QTY029, QTY030
                                        , QTY031, QTY032, QTY033, QTY034, QTY035, QTY036, QTY037, QTY038, QTY039, QTY040
                                        , QTY041, QTY042, QTY043, QTY044, QTY045, QTY046, QTY047, QTY048, QTY049, QTY050
                                        , QTY051, QTY052, QTY053, QTY054, QTY055, QTY056, QTY057, QTY058, QTY059, QTY060
                                        , QTY061, QTY062, QTY063, QTY064, QTY065, QTY066, QTY067, QTY068, QTY069, QTY070
                                        , QTY071, QTY072, QTY073, QTY074, QTY075, QTY076, QTY077, QTY078, QTY079, QTY080
                                        , QTY081, QTY082, QTY083, QTY084, QTY085, QTY086, QTY087, QTY088, QTY089, QTY090
                                        , QTY091, QTY092, QTY093, QTY094, QTY095, QTY096, QTY097, QTY098, QTY099, QTY100
                                        , QTY101, QTY102, QTY103, QTY104, QTY105, QTY106, QTY107, QTY108, QTY109, QTY110
                                        , QTY111, QTY112, QTY113, QTY114, QTY115, QTY116, QTY117, QTY118, QTY119, QTY120
                                        , QTY121, QTY122, QTY123, QTY124, QTY125, QTY126, QTY127, QTY128, QTY129, QTY130
                                        , QTY131, QTY132, QTY133, QTY134, QTY135, QTY136, QTY137, QTY138, QTY139, QTY140
                                        , QTY141, QTY142, QTY143, QTY144, QTY145, QTY146, QTY147, QTY148, QTY149, QTY150
                                        , QTY151, QTY152, QTY153, QTY154, QTY155, QTY156, QTY157, QTY158, QTY159, QTY160
                                        , QTY161, QTY162, QTY163, QTY164, QTY165, QTY166, QTY167, QTY168, QTY169, QTY170
                                        , QTY171, QTY172, QTY173, QTY174, QTY175, QTY176, QTY177, QTY178, QTY179, QTY180
                                        , QTY181, QTY182, QTY183, QTY184, QTY185, QTY186, QTY187, QTY188, QTY189, QTY190
                                        , QTY191, QTY192, QTY193, QTY194, QTY195, QTY196, QTY197, QTY198, QTY199, QTY200
                                        , QTY201, QTY202, QTY203, QTY204, QTY205, QTY206, QTY207, QTY208, QTY209, QTY210
                                        , QTY211, QTY212, QTY213, QTY214, QTY215, QTY216, QTY217, QTY218, QTY219, QTY220
                                        , QTY221, QTY222, QTY223, QTY224, QTY225, QTY226, QTY227, QTY228, QTY229, QTY230
                                        , QTY231, QTY232, QTY233, QTY234, QTY235, QTY236, QTY237, QTY238, QTY239, QTY240
                                        , QTY241, QTY242, QTY243, QTY244, QTY245, QTY246, QTY247, QTY248, QTY249, QTY250
                                        , QTY251, QTY252, QTY253, QTY254, QTY255, QTY256, QTY257, QTY258, QTY259, QTY260
                                        , QTY261, QTY262, QTY263, QTY264, QTY265, QTY266, QTY267, QTY268, QTY269, QTY270
                                        , QTY271, QTY272, QTY273, QTY274, QTY275, QTY276, QTY277, QTY278, QTY279, QTY280
                                        , QTY281, QTY282, QTY283, QTY284, QTY285, QTY286, QTY287, QTY288, QTY289, QTY290
                                        , QTY291, QTY292, QTY293, QTY294, QTY295, QTY296, QTY297, QTY298, QTY299, QTY300
                                        , QTY301, QTY302, QTY303, QTY304, QTY305, QTY306, QTY307, QTY308, QTY309, QTY310
                                        , QTY311, QTY312, QTY313, QTY314, QTY315, QTY316, QTY317, QTY318, QTY319, QTY320
                                        , QTY321, QTY322, QTY323, QTY324, QTY325, QTY326, QTY327, QTY328, QTY329, QTY330
                                        , QTY331, QTY332, QTY333, QTY334, QTY335, QTY336, QTY337, QTY338, QTY339, QTY340
                                        , QTY341, QTY342, QTY343, QTY344, QTY345, QTY346, QTY347, QTY348, QTY349, QTY350
                                        , QTY351, QTY352, QTY353, QTY354, QTY355, QTY356, QTY357, QTY358, QTY359, QTY360
                                        , QTY361, QTY362, QTY363, QTY364
                                        )
                           ) X
                 , ( SELECT A.BASIS_YYYYMMDD AS YYYYMMDD
                                     /*  MSSQL REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(..))) + CONVERT(NVARCHAR, ROW_NUMBER() OVER(..)) */
                                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS YYYYMMDD_COLUMN
                                  FROM SCM_SYS_CALENDAR_M A
                                 WHERE A.BASIS_YYYYMMDD     >= V_BATCH_CREATE_FROM_YYYYMMDD
                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                               ) Y
                WHERE X.YYYYMMDD_COLUMN = Y.YYYYMMDD_COLUMN
               AND Y.YYYYMMDD >= V_BATCH_CREATE_FROM_YYYYMMDD   /* @v_batch_PLAN_START_YYYYMMDD */
               AND X.DIVISION_ID          = V_BATCH_DIVISION_ID
               AND X.CREATE_FROM_YYYYMMDD = V_BATCH_CREATE_FROM_YYYYMMDD
               AND X.XLS_KEY1             = V_BATCH_XLS_KEY1
                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  2022.04.05   KSW            Daily/Monthly Bucket 변경건 적용 :: 변경된 Daily 건만 저장하는 로직추가 */
            /*  입력값이 -9 (변경건 아님) 건은 제외한다. */
            /* ------------------------------------------------------------------------------------------- */
            DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
             WHERE QTY = -9
                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  FROZEN 구간 UPDATE */
            /*  PLANT SITE(SCM_MST_SITE)의 SHIP_FROZEN ,PROD_FROZEN를 주단위로 변경하여 FROZEN 구간을 저장 내역에서 삭제한다. */
            /* ------------------------------------------------------------------------------------------- */
            IF V_BATCH_PLAN_TYPE IN ('MA', 'SE') AND V_BATCH_MEASURE IN ('PACK_PROD') THEN
                /*  MSSQL DELETE FROM #T FROM #T X INNER JOIN #S Y ON .. WHERE .. -> DELETE FROM t WHERE EXISTS (CV-063) */
                DELETE FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN X
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_XPGT_SCM_MST_SITE Y
                                 WHERE Y.DIVISION_ID = X.DIVISION_ID
                                   AND Y.SCM_SITE_ID = X.SCM_SITE_ID
                                   AND X.YYYYMMDD    < (CASE WHEN V_BATCH_PLAN_TYPE = 'MA' THEN Y.PROD_FROZEN_WEEK_DAY_MA ELSE Y.PROD_FROZEN_WEEK_DAY END) );   /* 7 */
            END IF;

               /*  PROD_PLAN_AMEND */
               /*  MSSQL : INSERT INTO SCP_ANL_PRODUCTION_PLAN (..) SELECT .. FROM ( MERGE .. OUTPUT $action, Inserted.* )
                   AS Changes(..) WHERE Action = 'INSERT'   (composable DML - Oracle 무대응)
                   = MERGE 로 실제 INSERT 된 행마다 MEASURE='PROD_PLAN_ENGINE', QTY=0 짝 행을 하나 더 넣는 로직이다.
                   MERGE 가 INSERT 할 집합 = ON 절에 매칭되지 않는 원천행이므로, 같은 조건을 NOT EXISTS 로 뽑아
                   MERGE 직전에 짝 행을 먼저 INSERT 한다. 짝 행의 MEASURE 는 'PROD_PLAN_ENGINE' 이고
                   ON 절/PK 모두 MEASURE 를 포함하므로 뒤따르는 MERGE 의 매칭 결과에 영향을 주지 않는다(1:1 등가). */
               /*  INSERT 일경우 PROD_PLAN_ENGINE/PROD_PLAN_AMEND 쌍으로 입력한다. */
               INSERT INTO SCP_ANL_PRODUCTION_PLAN
                    ( DIVISION_ID
                    , PLAN_START_YYYYMMDD
                    , PLAN_TYPE
                    , SEQ
                    , OPERATION_GROUP
                    /* , CELL_ITEM_ID */
                    , SCM_SITE_ID
                    , ITEM_ID
                    , LINE_ID
                    , OPERATION_ID
                    , MEASURE
                    , YYYYMMDD
                    , QTY
                    , ORIGIN_DIVISION_ID
                    , ELECTRODE_TYPE
                    , CELL_QTY
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE )
               SELECT Y.DIVISION_ID
                    , Y.PLAN_START_YYYYMMDD
                    , Y.PLAN_TYPE
                    , Y.SEQ
                    , Y.OPERATION_GROUP
                    /* , Inserted.CELL_ITEM_ID */
                    , Y.SCM_SITE_ID
                    , Y.ITEM_ID
                    , Y.LINE_ID
                    , NVL(Y.OPERATION_ID, '-') AS OPERATION_ID   /* 적재처 OPERATION_ID 는 NOT NULL 이라 빈값 센티넬 '-' (H-5) */
                    , 'PROD_PLAN_ENGINE' AS MEASURE
                    , Y.YYYYMMDD
                    , 0 AS QTY
                    , Y.ORIGIN_DIVISION_ID
                    , Y.ELECTRODE_TYPE
                    , Y.CELL_QTY
                    , V_BATCH_USER   AS CREATED_BY
                    , SYSDATE        AS CREATION_DATE
                    , V_BATCH_USER   AS LAST_UPDATED_BY
                    , SYSDATE        AS LAST_UPDATE_DATE
                 FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                WHERE NOT EXISTS ( SELECT 1
                                     FROM SCP_ANL_PRODUCTION_PLAN X
                                    WHERE 0 = 0
                        AND X.DIVISION_ID         = Y.DIVISION_ID          /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                        AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @v_batch_PLAN_START_YYYYMMDD */
                        AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @v_batch_PLAN_TYPE */
                        AND X.SEQ                 = Y.SEQ                  /* @v_batch_SEQ */
                        AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                        AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                        AND X.ITEM_ID             = Y.ITEM_ID
                        AND X.MEASURE             = Y.MEASURE
                        AND X.YYYYMMDD            = Y.YYYYMMDD
                        AND X.LINE_ID             = Y.LINE_ID
                        AND X.OPERATION_ID        = Y.OPERATION_ID
                        AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                        AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                                 )
                    ;

                       MERGE INTO SCP_ANL_PRODUCTION_PLAN X
                        USING ( SELECT DIVISION_ID
                                     , PLAN_START_YYYYMMDD
                                     , PLAN_TYPE
                                     , SEQ
                                     , OPERATION_GROUP
                                     /* , CELL_ITEM_ID */
                                     , SCM_SITE_ID
                                     , ITEM_ID
                                     , LINE_ID
                                     , OPERATION_ID
                                     , MEASURE
                                     , YYYYMMDD
                                     , QTY
                                     , ORIGIN_DIVISION_ID
                                     , ELECTRODE_TYPE
                                     , CELL_QTY
                                  FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                                 /* WHERE QTY > 0 */
                              ) Y
                           ON ( 0 = 0
                                AND X.DIVISION_ID         = Y.DIVISION_ID          /* @v_batch_division_id  2021.10.25 튜닝개선요청에 따른 변경 */
                                AND X.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD  /* @v_batch_PLAN_START_YYYYMMDD */
                                AND X.PLAN_TYPE           = Y.PLAN_TYPE            /* @v_batch_PLAN_TYPE */
                                AND X.SEQ                 = Y.SEQ                  /* @v_batch_SEQ */
                                AND X.OPERATION_GROUP     = Y.OPERATION_GROUP
                                AND X.SCM_SITE_ID         = Y.SCM_SITE_ID
                                AND X.ITEM_ID             = Y.ITEM_ID
                                AND X.MEASURE             = Y.MEASURE
                                AND X.YYYYMMDD            = Y.YYYYMMDD
                                AND X.LINE_ID             = Y.LINE_ID
                                AND X.OPERATION_ID        = Y.OPERATION_ID
                                AND X.ORIGIN_DIVISION_ID  = Y.ORIGIN_DIVISION_ID
                                AND NVL(X.ELECTRODE_TYPE, ' ') = NVL(Y.ELECTRODE_TYPE, ' ')
                              )
                        WHEN MATCHED THEN
                        UPDATE
                           SET X.QTY               = Y.QTY
                             /* , X.CREATED_BY         = @v_batch_user */
                             /* , X.CREATION_DATE      = GETDATE()     */
                             , X.LAST_UPDATED_BY  = V_BATCH_USER
                             , X.LAST_UPDATE_DATE = SYSDATE
                        WHEN NOT MATCHED THEN
                          INSERT ( DIVISION_ID
                                 , PLAN_START_YYYYMMDD
                                 , PLAN_TYPE
                                 , SEQ
                                 , OPERATION_GROUP
                                 /* , CELL_ITEM_ID */
                                 , SCM_SITE_ID
                                 , ITEM_ID
                                 , LINE_ID
                                 , OPERATION_ID
                                 , MEASURE
                                 , YYYYMMDD
                                 , QTY
                                 , ORIGIN_DIVISION_ID
                                 , ELECTRODE_TYPE
                                 , CELL_QTY
                                 , CREATED_BY
                                 , CREATION_DATE
                                 , LAST_UPDATED_BY
                                 , LAST_UPDATE_DATE )
                          VALUES ( Y.DIVISION_ID
                                 , Y.PLAN_START_YYYYMMDD
                                 , Y.PLAN_TYPE
                                 , Y.SEQ
                                 , Y.OPERATION_GROUP
                                 /* , Y.CELL_ITEM_ID */
                                 , Y.SCM_SITE_ID
                                 , Y.ITEM_ID
                                 , Y.LINE_ID
                                 , Y.OPERATION_ID
                                 , Y.MEASURE
                                 , Y.YYYYMMDD
                                 , Y.QTY
                                 , Y.ORIGIN_DIVISION_ID
                                 , Y.ELECTRODE_TYPE
                                 , Y.CELL_QTY
                                 , V_BATCH_USER
                                 , SYSDATE
                                 , V_BATCH_USER
                                 , SYSDATE )
                                 ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_H : History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SELECT top 10 * FROM dbo.SCP_ANL_PRODUCTION_PLAN_H WITH (NOLOCK)      HISTORY_SEQ */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_H */
                      INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
                           ( HISTORY_SEQ
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
                           , DIVISION_ID
                           , PLAN_START_YYYYMMDD
                           , PLAN_TYPE
                           , SEQ
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , MEASURE
                           , YYYYMMDD
                           , QTY
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN
                           ;

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_FIX : FIX 입력 */
            /* ------------------------------------------------------------------------------------------- */
                      UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
                         SET ( QTY
                             , ATTRIBUTE1
                             , LAST_UPDATED_BY
                             , LAST_UPDATE_DATE ) =
                             ( SELECT Y.QTY
                                    , 'Y'
                                    , V_BATCH_USER
                                    , SYSDATE
                                 FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                                WHERE 0 = 0
                                  AND X.DIVISION_ID       = Y.DIVISION_ID
                                  AND X.OPERATION_GROUP   = Y.OPERATION_GROUP
                                  AND X.SCM_SITE_ID       = Y.SCM_SITE_ID
                                  AND X.ITEM_ID           = Y.ITEM_ID
                                  AND X.LINE_ID           = Y.LINE_ID
                                  AND X.OPERATION_ID      = Y.OPERATION_ID
                                  AND X.YYYYMMDD          = Y.YYYYMMDD
                                  AND ROWNUM              = 1 )
                       WHERE EXISTS ( SELECT 1
                                        FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                                       WHERE 0 = 0
                                         AND X.DIVISION_ID       = Y.DIVISION_ID
                                         AND X.OPERATION_GROUP   = Y.OPERATION_GROUP
                                         AND X.SCM_SITE_ID       = Y.SCM_SITE_ID
                                         AND X.ITEM_ID           = Y.ITEM_ID
                                         AND X.LINE_ID           = Y.LINE_ID
                                         AND X.OPERATION_ID      = Y.OPERATION_ID
                                         AND X.YYYYMMDD          = Y.YYYYMMDD );

            /* ------------------------------------------------------------------------------------------- */
            /*  SCP_ANL_PRODUCTION_PLAN_FIX : FIX History 입력 */
            /* ------------------------------------------------------------------------------------------- */
            /*  SET @n_history_seq = NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H */
            /*  SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H */
                      INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
                           ( HISTORY_SEQ
                           , FIX_ID
                           , DIVISION_ID
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , CREATED_BY
                           , CREATION_DATE
                           , LAST_UPDATED_BY
                           , LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , HISTORY_CREATION_DATE )
                      SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
                           , FIX_ID
                           , DIVISION_ID
                           , OPERATION_GROUP
                           , SCM_SITE_ID
                           , ITEM_ID
                           , LINE_ID
                           , OPERATION_ID
                           , YYYYMMDD
                           , QTY
                           , FIX_REASON
                           , ORIGIN_DIVISION_ID
                           , ELECTRODE_TYPE
                           , V_BATCH_USER   AS CREATED_BY
                           , SYSDATE        AS CREATION_DATE
                           , V_BATCH_USER   AS LAST_UPDATED_BY
                           , SYSDATE        AS LAST_UPDATE_DATE
                           /* ,ATTRIBUTE1
                              ,ATTRIBUTE2
                              ,ATTRIBUTE3
                              ,ATTRIBUTE4
                              ,ATTRIBUTE5
                              ,ATTRIBUTE6
                              ,ATTRIBUTE7
                              ,ATTRIBUTE8
                              ,ATTRIBUTE9
                              ,ATTRIBUTE10 */
                           , SYSDATE        AS HISTORY_CREATION_DATE
                        FROM SCP_ANL_PRODUCTION_PLAN_FIX
                       WHERE ATTRIBUTE1 = 'Y'
                           ;

              /*  History 구분을 위해 원상복구 */
              UPDATE SCP_ANL_PRODUCTION_PLAN_FIX X   /* FIX_ID, DIVISION_ID, OPERATION_GROUP, SCM_SITE_ID, ITEM_ID, LINE_ID, OPERATION_ID, YYYYMMDD */
                 SET X.ATTRIBUTE1 = NULL       /* History 구분을 위해 원상복구 */
               WHERE EXISTS ( SELECT 1
                                FROM GT_XPGT_SCP_ANL_PRODUCTION_PLAN Y
                               WHERE 0 = 0
                                 AND X.DIVISION_ID     = Y.DIVISION_ID
                                 AND X.OPERATION_GROUP = Y.OPERATION_GROUP
                                 AND X.SCM_SITE_ID     = Y.SCM_SITE_ID
                                 AND X.ITEM_ID         = Y.ITEM_ID
                                 AND X.LINE_ID         = Y.LINE_ID
                                 AND X.OPERATION_ID    = Y.OPERATION_ID
                                 AND X.YYYYMMDD        = Y.YYYYMMDD )
                 AND X.ATTRIBUTE1 = 'Y';

            END IF;

            /* --------------------------------------------------------- */
            /*  FROZEN 구간 복구 */
            /* --------------------------------------------------------- */
            DBMS_OUTPUT.PUT_LINE(P_CREATE_FROM_YYYYMMDD);
            DBMS_OUTPUT.PUT_LINE(P_CREATE_TO_YYYYMMDD);
            /* ------------------------------------------------------------------------------------------- */
            /*  전체 임시 테이블 생성  (#SCP_XLS_PSI_GLOBAL_MODIFY) */
            /* ------------------------------------------------------------------------------------------- */
            /*                DROP TABLE #SCP_XLS_PSI_GLOBAL_MODIFY
                CREATE TABLE #SCP_XLS_PSI_GLOBAL_MODIFY( XLS_KEY1 INT NOT NULL, DIVISION_ID NVARCHAR(30) NOT NULL,
                  CREATE_FROM_YYYYMMDD NVARCHAR(8) NOT NULL, QTY001 NUMERIC(20,10) NULL, .. QTY364 NUMERIC(20,10) NULL ) */
            DELETE FROM GT_XPGT_SCP_XLS_PSI_GLOBAL_MODIFY;

            DBMS_OUTPUT.PUT_LINE('66666666666666666666666666666');

            V_X_ITEM_ID         := '';
            /*  SCP_ANL_SHIPMENT_PLAN_FG/SEMI PK Parameter */
            V_X_OPERATION_GROUP := '';   /* BIZ_TYPE */
            V_X_PROJECT_CODE    := '';
            V_X_TO_SITE         := '';
            V_X_INCOTERMS       := '';
            V_X_FROM_SITE       := '';   /* SCM_SITE_ID */
            V_X_BOD_ID          := '';
            /*  SCP_ANL_PRODUCTION_PLAN PK Parameter */
            V_X_LINE_ID         := '';
            V_X_OPERATION_ID    := '';

            /*  MSSQL 대입형 SELECT : 0행이면 기존값 유지, 다행이면 마지막 행 -> 커서 FOR 루프(SELECT INTO 금지). */
            FOR R IN ( SELECT OPERATION_GROUP
                            , ITEM_ID
                            , PROD_LINE
                            , ATTRIBUTE9
                            , PROJECT_CODE
                            , TO_SITE
                            , INCOTERMS
                            , FROM_SITE
                            , BOD_ID
                         FROM SCP_XLS_PSI_GLOBAL_SMALL_PACK
                        WHERE DIVISION_ID          = V_BATCH_DIVISION_ID
                          AND PLAN_START_YYYYMMDD  = V_BATCH_PLAN_START_YYYYMMDD
                          AND CREATE_FROM_YYYYMMDD = V_BATCH_CREATE_FROM_YYYYMMDD
                          AND PLAN_TYPE            = V_BATCH_PLAN_TYPE
                          AND SEQ                  = V_BATCH_SEQ
                          AND XLS_KEY1             = V_BATCH_XLS_KEY1
                     )
            LOOP
                V_X_OPERATION_GROUP := R.OPERATION_GROUP;
                V_X_ITEM_ID         := R.ITEM_ID;
                V_X_LINE_ID         := R.PROD_LINE;
                V_X_OPERATION_ID    := R.ATTRIBUTE9;
                V_X_PROJECT_CODE    := R.PROJECT_CODE;
                V_X_TO_SITE         := R.TO_SITE;
                V_X_INCOTERMS       := R.INCOTERMS;
                V_X_FROM_SITE       := R.FROM_SITE;
                V_X_BOD_ID          := R.BOD_ID;
            END LOOP;

        /* --------------------------------------------------------- */
        /*  FROZEN 구간 복구 */
        /* --------------------------------------------------------- */
        /*  2022.08.25 PACK_PROD 만 FROZEN 처리되는 것으로 오류수정 */
        IF V_BATCH_MEASURE = 'PACK_PROD' THEN   /* XXXXXX */
            /* ------------------------------------------------------------------------------------------- */
            /*  저장후 시물레이션 데이터 UPDATE */
            /* ------------------------------------------------------------------------------------------- */
            /*  MSSQL SELECT @v = @v + .. FROM (..) ORDER BY .. (행별 문자열 누적 트릭, EP-013) */
            V_MQRY_SUM2 := '';
            FOR R IN ( SELECT ' SUM(CASE WHEN YYYYMMDD = ''' || A.YYYYMMDD || '''    THEN QTY ELSE 0 END ) AS '
                              || 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.YYYYMMDD)), 3, '0') AS COL_EXPR
                         FROM ( SELECT A.BASIS_YYYYMMDD                      AS YYYYMMDD
                                     , A.BASIS_YYYYMMDD || TO_CHAR(31)       AS SORT_ORDER_NO
                                  FROM SCM_SYS_CALENDAR_M A
                                 /*  WHERE A.BASIS_YYYYMMDD >= @p_plan_start_yyyymmdd
                                       AND A.BASIS_YYYYMMDD <  @p_to_yyyymmdd  */
                                 WHERE A.BASIS_YYYYMMDD     >= V_BATCH_CREATE_FROM_YYYYMMDD
                                   AND A.BASIS_YYYYMMDD     <  V_BATCH_CREATE_TO_YYYYMMDD
                                 GROUP BY A.BASIS_YYYYMMDD
                              ) A
                        ORDER BY A.SORT_ORDER_NO )
            LOOP
                V_MQRY_SUM2 := V_MQRY_SUM2 || ',' || R.COL_EXPR || '' || CHR(10);
            END LOOP;

            V_MEXEC2 := '';
            /*  MSSQL INSERT INTO #.. WITH (TABLOCK) : TABLOCK 힌트는 Oracle 무대응이라 제거(H-13) */
            V_MEXEC2 := V_MEXEC2 || ' INSERT INTO GT_XPGT_SCP_XLS_PSI_GLOBAL_MODIFY  ' || CHR(10);

            /* ------------------------------------------------------------------------------------------- */
            /*  'SHIP_PLAN' */
            /*  PK : DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, YYYYMMDD, BIZ_TYPE, ITEM_ID, PROJECT_CODE, TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, MEASURE */
            /* ------------------------------------------------------------------------------------------- */
            V_MFG := '';
            V_MFG := V_MFG || ' SELECT  ''' || TO_CHAR(V_BATCH_XLS_KEY1) || ''' AS XLS_KEY1  ' || CHR(10);
            V_MFG := V_MFG || '         ,''' || V_BATCH_DIVISION_ID || ''' AS DIVISION_ID  ' || CHR(10);
            V_MFG := V_MFG || '         ,''' || V_BATCH_CREATE_FROM_YYYYMMDD || ''' AS CREATE_FROM_YYYYMMDD  ' || CHR(10);
            V_MFG := V_MFG || '           ' || V_MQRY_SUM2 || '                       ' || CHR(10);
            V_MFG := V_MFG || '    FROM SCP_ANL_SHIPMENT_PLAN_FG  ' || CHR(10);
            V_MFG := V_MFG || '    WHERE 0 = 0                                 ' || CHR(10);
